/* @lc app=leetcode id=3080 lang=kotlin */ class Solution { fun unmarkedSumArray(nums: IntArray, queries: Array<IntArray>): LongArray = BooleanArray(nums.size).let { marked -> nums.indices.sortedWith(compareBy({ nums[it] }, { it })).toIntArray().let { sorted -> longArrayOf(nums.fold(0L, Long::plus), 0L).let { st -> LongArray(queries.size) { i -> queries[i].let { q -> (if (!marked[q[0]]) marked.set(q[0], true).also { st[0] -= nums[q[0]] } else Unit).let { intArrayOf(0).run { while (this[0] < q[1] && st[1] < sorted.size) sorted[st[1]++.toInt()].let { idx -> if (!marked[idx]) marked.set(idx, true).also { st[0] -= nums[idx] }.also { this[0]++ } } } } }.let { st[0] } } } } } }